/*---------------------------------------------------------------------------*/
/* Peripheral Instance Traversal Macros                                      */
/*---------------------------------------------------------------------------*/

/**
 * \brief           STM32 GPIO instance traversal macro
 *
 * This macro expands to call the provided function for each enabled
 * GPIO instance. Used by the device registration system.
 *
 * Example:
 *   NX_DEFINE_INSTANCE_STM32_GPIO(MY_REGISTER_FUNC)
 *   expands to:
 *   MY_REGISTER_FUNC(A, 0) MY_REGISTER_FUNC(A, 5)
 */
#define NX_DEFINE_INSTANCE_STM32_GPIO(fn) \
    fn(A, 0); \
    fn(A, 5);

/**
 * \brief           STM32 UART instance traversal macro
 *
 * This macro expands to call the provided function for each enabled
 * UART instance. Used by the device registration system.
 *
 * Example:
 *   NX_DEFINE_INSTANCE_STM32_UART(MY_REGISTER_FUNC)
 *   expands to:
 *   MY_REGISTER_FUNC(0)
 */
#define NX_DEFINE_INSTANCE_STM32_UART(fn) \
    _STM32_UART_INSTANCE_0(fn)

#ifdef NX_CONFIG_INSTANCE_STM32_UART_0
#define _STM32_UART_INSTANCE_0(fn) fn(0)
#define NX_CONFIG_UART0_ENABLED 1
#else
#define _STM32_UART_INSTANCE_0(fn)
#define NX_CONFIG_UART0_ENABLED 0
#endif

